class Solution {
    TreeNode* parse(const string& s, int& index) {
        int sign = 1;
        if (s[index] == '-') {
            sign = -1;
            ++index;
        }
        int value = 0;
        while (index < static_cast<int>(s.size()) && isdigit(s[index])) {
            value = value * 10 + (s[index++] - '0');
        }
        TreeNode* node = new TreeNode(sign * value);
        if (index < static_cast<int>(s.size()) && s[index] == '(') {
            ++index;
            if (s[index] != ')') {
                node->left = parse(s, index);
            }
            ++index;
        }
        if (index < static_cast<int>(s.size()) && s[index] == '(') {
            ++index;
            if (s[index] != ')') {
                node->right = parse(s, index);
            }
            ++index;
        }
        return node;
    }

public:
    TreeNode* str2tree(string s) {
        if (s.empty()) {
            return nullptr;
        }
        int index = 0;
        return parse(s, index);
    }
};
